from research_helpers import *
A=ev('https://www.sec.gov/Archives/edgar/data/865415/000119312515308192/d87166d10k.htm','Adept2015 issuer product inventory reviewed. Named robot, controller, vision and software offerings retained; historical availability not represented as current sales.')
B=ev('https://www.sec.gov/Archives/edgar/data/865415/000119312514320025/d768936d10k.htm','Adept2014 issuer confirms Cobra i600/i800 embedded-control models.')
C=ev('https://www.sec.gov/Archives/edgar/data/865415/000119312507201853/d10k.htm','Adept issuer confirms Viper s1300/s1700 and historical single-axis control products.')
O=ev('https://www.omron.com/media/press/2015/10/c1024.html','Completed Omron acquisition confirmed October2015; not used to attribute every Omron product to Adept.')
Q=ev('https://www.ia.omron.com/products/family/3865/specification.html','Current successor catalogue identifies Quattro650H/650HS/800H/800HS configurations; generic reach ranges not invented into additional models.')
E=ev('https://www.ia.omron.com/products/family/3864/specification.html','Current successor eCobra600/800 catalogue, Lite/Standard/Pro tiers retained as attributes rather than separate duplicate family records.')
V=ev('https://www.ia.omron.com/data_pdf/cat/industrial%20robots_i822-e1_14_1_csm1050308.pdf?id=3864','Successor catalogue identifies Adept-branded Viper650/850 and eCobra600/800 lineage.')
S=ev('https://www.sec.gov/Archives/edgar/data/865415/000119312505192408/d10k.htm','Adept2005 issuer describes SmartModules single-axis mechanisms and SmartAmp integrated single-axis controller/power amplifier.')
ps=[]
for n in ['650H','650HS','800H','800HS']:ps.append(p('Adept Quattro '+n,'Four-axis parallel industrial robot.',Q,'commercial',typ='product',sector='robotics',sub='industrial_robotics',evidence=[A,Q,O]))
for n in ['650','850']:ps.append(p('Adept Viper s'+n,'Six-axis articulated industrial robot.',V,'commercial',typ='product',sector='robotics',sub='industrial_robotics',evidence=[A,V,O]))
for n in ['1300','1700']:ps.append(p('Adept Viper s'+n,'Historical six-axis industrial robot.',C,typ='product',sector='robotics',sub='industrial_robotics'))
for n in ['s350','s600','s800','s800 inverted']:ps.append(p('Adept Cobra '+n,'Historical SCARA robot.',A,typ='product',sector='robotics',sub='industrial_robotics'))
for n in ['i600','i800']:ps.append(p('Adept Cobra '+n,'Historical embedded-control SCARA robot.',B,typ='product',sector='robotics',sub='industrial_robotics'))
for n in ['600','800']:ps.append(p('Adept eCobra '+n,'SCARA robot product family.',E,'commercial',typ='product',sector='robotics',sub='industrial_robotics',attributes={'catalogued_performance_tiers':['Lite','Standard','Pro']},evidence=[A,E,O]))
for n,d in [('Python','Cartesian linear robot modules.'),('Hornet 565','Parallel picking robot.'),('Lynx','Autonomous mobile robot.'),('Lynx Courier','Mobile transport configuration.'),('Lynx Transporter-Semi','Wafer-pod transport robot.'),('Lynx Handler-Semi','Wafer-pod handling robot.'),('Lynx Conveyor','Mobile conveyor configuration.'),('Lynx Cart Transporter','Autonomous cart transport configuration.')]:ps.append(p('Adept '+n,d,A,typ='product',sector='robotics',sub='industrial_robotics'))
for n,d in [('Enterprise Manager','Mobile-robot fleet management system.'),('SmartController','Robot motion controller.'),('SmartVision','Industrial machine-vision processor.'),('ACE','Robot workcell configuration software.'),('ACE PackXpert','Packaging automation software.'),('AdeptSight','Robot vision software extension.'),('ePLC Connect','Robot PLC-connectivity software.'),('Mobile Planner','Mobile-robot navigation software.')]:ps.append(p(n if n=='AdeptSight'else'Adept '+n,d,A,typ='product',sector='robotics',sub='autonomy_and_components'))
for n in ['AnyFeeder','FlexiBowl']:ps.append(p('Adept '+n,'Historical flexible robotic part feeder.',A,roles=['commercial_partner'],typ='product',sector='robotics',sub='autonomy_and_components'))
for n,d in [('SmartModules','Historical single-axis robot mechanisms.'),('SmartAmp','Historical single-axis controller/amplifier.')]:ps.append(p('Adept '+n,d,S,typ='product',sector='robotics',sub='autonomy_and_components'))
cs=[company('Adept Technology Inc',ps,[A,B,C,O,Q,E,V,S],'36 named historical and successor-corroborated robots/components/software captured. Quattro/Viper/eCobra current successor evidence checked; other old names availability unresolved. Performance tiers retained as configurations. Omron acquisition not used to claim unrelated Omron/TM robots. Further mobile model variants, historical controllers/software and exact configuration specifications require followup.')]
(out/'batch-0062.json').write_text(json.dumps({'companies':cs},indent=2));print(len(ps))
